SELECT platform,repo_id,repo_name,formatDateTime(created_at,'%Y-%m') month,round(sum(openrank),4) openrank FROM global_openrank WHERE type='Repo' AND platform='AtomGit' AND (org_id IN (SELECT entity_id FROM flatten_labels WHERE id=':companies/huawei/cann' AND platform='AtomGit' AND entity_type='Org') OR repo_id IN (SELECT entity_id FROM flatten_labels WHERE id=':companies/huawei/cann' AND platform='AtomGit' AND entity_type='Repo')) AND created_at>='2025-07-01' AND created_at<'2026-11-01' GROUP BY platform,repo_id,repo_name,month ORDER BY month,openrank DESC FORMAT JSON